/*
 * DB — is the generated schema binding still generated, still fresh, and still
 * actually bound?
 *
 * ADR-416's data gate, rule 1: every external name is generated, never typed.
 * A generated type only delivers that while all three of those hold, and each
 * fails in its own quiet way, so each is its own rule with its own marker.
 *
 *   [DB-STAMP]    src/lib/supabase/database.types.ts exists and carries a
 *                 parseable `@migrations-sha256` line. FAILS CLOSED: a missing
 *                 file, or a file regenerated by hand with a bare
 *                 `supabase gen types > ...` that dropped the stamp, is
 *                 reported rather than skipped. A freshness rule that quietly
 *                 skips when it cannot find its input is a freshness rule that
 *                 has stopped asking anything.
 *
 *   [DB-FRESH]    That stamp matches supabase/migrations/ as it stands now.
 *                 The file is generated AND committed, which is the rot shape
 *                 ADR-416 names: nothing about a stale one looks stale, and a
 *                 renamed column then surfaces as a wrong number rather than a
 *                 red build. Same defect class as EX-REGISTRY, same remedy.
 *
 *   [DB-BINDING]  Every Supabase client constructed in src/ passes the schema
 *                 generic, and the unbound `SupabaseClient` type is imported
 *                 nowhere but the module that binds it. Without this the type
 *                 can be perfectly fresh and reach nothing: an unbound client
 *                 accepts any table name and any RPC name and returns `any`, so
 *                 one new file reaching past the binding silently opts the whole
 *                 surface back out.
 *
 *   [DB-ONEWAY]   No direct table write anywhere in src/. Rule 3 of the same
 *                 gate: one way to reach data. Every write goes through an RPC,
 *                 where the rules live — a bid that cannot exceed a budget, a
 *                 score that is derived rather than stored. A `.insert()` beside
 *                 an RPC is a second door into the same room, and the one with
 *                 no lock on it.
 *
 *                 THERE IS NO EXCEPTION LIST, and that is deliberate rather than
 *                 lucky. The three writes that existed on 2026-08-19 were all
 *                 converted (20260819010000) instead of two of them being
 *                 sanctioned, precisely so this rule has nothing to grandfather.
 *                 An exception manifest is a thing later writes quietly join.
 *                 READS ARE UNTOUCHED: `.from(...).select(...)` is how every
 *                 page loads, and the gate is about who may CHANGE state.
 *
 * WHAT THIS CHECK CANNOT SEE. The stamp fingerprints migration FILES, not the
 * database. A schema change made in the dashboard leaves it fresh and the types
 * wrong. Reading the live schema would need network and a token on every run,
 * which is not a gate. The migrations directory is the offline truth available,
 * and `npm run spike:adr` is what tests the other direction.
 *
 * Exit 1 on violation, 2 when it could not run.
 */
import { readdirSync, readFileSync, existsSync, statSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve, join, relative } from "node:path";

import {
  migrationsFingerprint,
  readStamp,
  MIGRATIONS_DIR,
  TYPES_FILE,
} from "./types-stamp.mjs";

const ROOT =
  process.env.GOVERNANCE_ROOT ??
  resolve(dirname(fileURLToPath(import.meta.url)), "..");

const REGEN = "Run `npm run types:gen`.";

// The one module allowed to name the unbound client, because binding it is what
// the module is for. Listed rather than pattern-matched: an exemption a regex
// grants is an exemption nobody can enumerate.
const BINDING_MODULE = join("src", "lib", "supabase", "types.ts");

// Factories whose FIRST type parameter is the schema. A call to one of these
// without a generic is an unbound client no matter how well typed the rest of
// the file is.
const FACTORIES = ["createClient", "createServerClient", "createBrowserClient"];
const CLIENT_PACKAGES = ["@supabase/supabase-js", "@supabase/ssr"];

const failures = { stamp: [], fresh: [], binding: [], oneway: [] };

// --- [DB-STAMP] + [DB-FRESH] ------------------------------------------------
const typesPath = join(ROOT, TYPES_FILE);

if (!existsSync(join(ROOT, MIGRATIONS_DIR))) {
  console.error(`DB could not run: no ${MIGRATIONS_DIR}/ under ${ROOT}.`);
  process.exit(2);
}

const expected = migrationsFingerprint(ROOT);

if (!existsSync(typesPath)) {
  failures.stamp.push(
    `${TYPES_FILE} does not exist — nothing is generated, so nothing is bound.`
  );
} else {
  const stamp = readStamp(readFileSync(typesPath, "utf8"));
  if (!stamp) {
    failures.stamp.push(
      `${TYPES_FILE} carries no @migrations-sha256 line. It was written by something other than the generator — most likely a bare "supabase gen types" redirect, which produces a correct file with no way to tell later whether it still is.`
    );
  } else if (stamp !== expected) {
    failures.fresh.push(
      `${TYPES_FILE} was generated against a different ${MIGRATIONS_DIR}/.\n      stamped: ${stamp}\n      now:     ${expected}`
    );
  }
}

// --- [DB-BINDING] -----------------------------------------------------------
const SRC = join(ROOT, "src");
const walk = (d, out = []) => {
  for (const n of readdirSync(d)) {
    const p = join(d, n);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.tsx?$/.test(p)) out.push(p);
  }
  return out;
};

const escapeForRe = (s) => s.replace(/[.*+?^${}()|[\]\\/@-]/g, "\\$&");

if (existsSync(SRC)) {
  for (const file of walk(SRC)) {
    const rel = relative(ROOT, file);
    // NOT COMMENT-BLANKED, and that is deliberate (Ruling 64 round 2 asks for
    // every read site to say which it is). The blanker exists because a scan
    // SATISFIED by raw text can be fooled by a comment describing the thing —
    // a false NEGATIVE, silent, permanent. These two rules point the other way:
    // they DETECT rather than confirm, so a commented-out `.from("x").insert(`
    // or `createClient(` costs a false POSITIVE — loud, blocking, and fixed by
    // deleting dead code, which is the outcome we want anyway. Blanking here
    // would only ever make the check see less, and "sees less" is the failure
    // mode being removed everywhere else in this commit.
    const text = readFileSync(file, "utf8");

    // --- [DB-ONEWAY] ---
    // Anchored on `.from("<table>")` so it asks about a TABLE write and cannot
    // match a Set, a Map or an array method — `next.delete(id)` inside a picker
    // is not a database call, and a bare search for `.delete(` reports four of
    // them in this repo today. The write verb may sit on the next line, since
    // that is how prettier breaks a chained query.
    for (const m of text.matchAll(
      /\.from\("([a-z_]+)"\)\s*\.\s*(insert|update|delete|upsert)\s*\(/g
    )) {
      const line = text.slice(0, m.index).split("\n").length;
      failures.oneway.push(
        `${rel}:${line} writes ${m[1]} directly with .${m[2]}() — every write goes through an RPC, which is where the rules live.`
      );
    }

    for (const pkg of CLIENT_PACKAGES) {
      // Each import of a client package, with the local names it binds — an
      // alias included, since "createClient as createServiceClient" is the same
      // factory under a name a substring search would miss. This repo had one.
      const importRe = new RegExp(
        `import\\s+(type\\s+)?\\{([^}]*)\\}\\s+from\\s+"${escapeForRe(pkg)}"`,
        "g"
      );
      for (const m of text.matchAll(importRe)) {
        const isTypeOnlyImport = Boolean(m[1]);
        for (const raw of m[2].split(",")) {
          const clause = raw.trim();
          if (!clause) continue;
          const typeOnlyMember = /^type\s+/.test(clause);
          const [imported, local = imported] = clause
            .replace(/^type\s+/, "")
            .split(/\s+as\s+/)
            .map((s) => s.trim());

          if (imported === "SupabaseClient" && rel !== BINDING_MODULE) {
            failures.binding.push(
              `${rel} imports the UNBOUND SupabaseClient from "${pkg}". Import it from @/lib/supabase, which is the same name already bound to the schema.`
            );
            continue;
          }
          if (!FACTORIES.includes(imported)) continue;
          if (isTypeOnlyImport || typeOnlyMember) continue;

          // A call with no angle bracket between the name and the paren is unbound.
          const callRe = new RegExp(`\\b${escapeForRe(local)}\\s*(<|\\()`, "g");
          for (const call of text.matchAll(callRe)) {
            if (call[1] === "<") continue;
            const line = text.slice(0, call.index).split("\n").length;
            failures.binding.push(
              `${rel}:${line} calls ${local}() with no schema generic — an unbound client accepts any table name and any RPC name.`
            );
          }
        }
      }
    }
  }
}

// ---------------------------------------------------------------------------
const total =
  failures.stamp.length +
  failures.fresh.length +
  failures.binding.length +
  failures.oneway.length;

if (failures.stamp.length) {
  console.error("\n[DB-STAMP] THE GENERATED SCHEMA IS MISSING OR UNSTAMPED:");
  for (const f of failures.stamp) console.error("  " + f);
  console.error("      -> " + REGEN);
}
if (failures.fresh.length) {
  console.error("\n[DB-FRESH] THE GENERATED SCHEMA IS STALE:");
  for (const f of failures.fresh) console.error("  " + f);
  console.error(
    "      -> " +
      REGEN +
      " Push the migration first — the types come from the hosted schema, not from the files."
  );
}
if (failures.oneway.length) {
  console.error("\n[DB-ONEWAY] A TABLE IS WRITTEN WITHOUT GOING THROUGH AN RPC:");
  for (const f of failures.oneway) console.error("  " + f);
  console.error(
    "      -> Add the write to a SECURITY DEFINER function in supabase/migrations/ and call it with .rpc(). There is no exception list on purpose."
  );
}
if (failures.binding.length) {
  console.error("\n[DB-BINDING] A SUPABASE CLIENT IS NOT BOUND TO THE SCHEMA:");
  for (const f of failures.binding) console.error("  " + f);
  console.error(
    "      -> A generated type that no client carries is a file, not a gate."
  );
}

const migrationCount = readdirSync(join(ROOT, MIGRATIONS_DIR)).filter((f) =>
  f.endsWith(".sql")
).length;
console.log(
  `\nDB schema binding: ${migrationCount} migration(s) fingerprinted, ${failures.stamp.length} stamp problem(s), ${failures.fresh.length} stale, ${failures.binding.length} unbound client(s), ${failures.oneway.length} direct write(s).`
);

if (total) {
  console.error("DB FAILED.");
  process.exit(1);
}
console.log(
  "DB PASSED — the schema type is generated, fresh against the migrations, carried by every client, and no table is written outside an RPC."
);
